    def _backup_file_path(self, backup_file):
        return os.path.join(app.config['BACKUP_DIR'], backup_file)

    def list_backup_files(self):
        return [
            f for f in os.listdir(app.config['BACKUP_DIR'])
            if f.endswith('.tar.gz')
            and self.is_safe_path(app.config['BACKUP_DIR'], self._backup_file_path(f))
        ]

    def create_backup(self, config_path):
        if not os.path.exists(config_path):
            return None
        if not self._is_allowed_path(config_path):
            return None
        timestamp = datetime.now().strftime('%Y%m%d_%H%M%S')
        backup_name = f'config_backup_{timestamp}.tar.gz'
        backup_path = self._backup_file_path(backup_name)
