from flask import Flask, abort, escape, render_template_string, request, send_file
from werkzeug.utils import secure_filename

app = Flask(__name__)
app.config['LOG_DIR'] = os.path.abspath('/var/log/app_logs')
app.config['MAX_LOG_SIZE'] = 1024 * 1024
app.config['ALLOWED_LOG_EXTENSIONS'] = {'.log', '.txt'}

LOG_VIEW_TEMPLATE = """
<!DOCTYPE html>
<html>
<head>
    <title>Log Viewer - {{ filename }}</title>
</head>
<body>
    <h1>Log File: {{ filename }}</h1>
    <pre>{{ log_content }}</pre>
</body>
</html>
"""


class LogManager:

    def __init__(self):
        os.makedirs(app.config['LOG_DIR'], exist_ok=True)

    def _log_path(self, filename):
        return os.path.join(app.config['LOG_DIR'], filename)

    def is_safe_path(self, path):
        base_path = os.path.abspath(app.config['LOG_DIR'])
        requested_path = os.path.abspath(path)
        return requested_path.startswith(base_path + os.sep)

    def is_valid_log_filename(self, filename):
        if not filename:
            return False
        if '../' in filename or '~' in filename:
            return False
        return filename.endswith(tuple(app.config['ALLOWED_LOG_EXTENSIONS']))

    def rotate_logs(self):
        log_dir = app.config['LOG_DIR']
        max_size = app.config['MAX_LOG_SIZE']
        for log_file in os.listdir(log_dir):
            file_path = os.path.join(log_dir, log_file)
            if os.path.exists(file_path) and os.path.getsize(file_path) > max_size:
                timestamp = datetime.now().strftime('%Y%m%d_%H%M%S')
                new_path = os.path.join(log_dir, f'{log_file}.{timestamp}.bak')
                if self.is_safe_path(new_path):
                    os.rename(file_path, new_path)

    def get_log_file(self, filename, max_lines=1000):
        if not self.is_valid_log_filename(filename):
            return None
        file_path = self._log_path(filename)
        if not self.is_safe_path(file_path):
            return None
        try:
            if not os.path.isfile(file_path):
                return None
            with open(file_path, 'r') as f:
                lines = []
                for i, line in enumerate(f):
                    if i >= max_lines:
                        break
                    lines.append(line)
                return ''.join(lines)
        except Exception:
            return None

    def write_log(self, filename, message):
        if not self.is_valid_log_filename(filename):
            return False
        file_path = self._log_path(filename)
        if not self.is_safe_path(file_path):
            return False
        try:
            timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
            with open(file_path, 'a') as f:
                f.write(f'[{timestamp}] {message}\n')
            return True
        except Exception:
            return False


