                self.loaded_plugins[plugin_name] = {
                    'type': 'python',
                    'path': plugin_path,
                    'loaded_at': datetime.now(),
                }
                return True
        return False

    @staticmethod
    def _restricted_builtins() -> Dict[str, Any]:
        """Return the limited set of builtins exposed to Python plugin code."""
        return {
            'str': str,
            'int': int,
            'float': float,
            'bool': bool,
            'list': list,
            'dict': dict,
            'tuple': tuple,
            'range': range,
            'len': len,
            'sum': sum,
            'min': min,
            'max': max,
            'abs': abs,
            'round': round,
        }

    def _load_json_plugin(self, plugin_path: str) -> bool:
        with open(plugin_path, 'r', encoding='utf-8') as f:
            try:
