from typing import Any, Dict

# Builtins exposed to dynamically loaded Python plugins.
_SAFE_BUILTINS = {
    'str': str,
    'int': int,
    'float': float,
    'bool': bool,
    'list': list,
    'dict': dict,
    'tuple': tuple,
    'range': range,
    'len': len,
    'sum': sum,
    'min': min,
    'max': max,
    'abs': abs,
    'round': round,
}

_MENU = (
    '\n1. Load plugin\n'
    '2. Create document\n'
    '3. Process document\n'
    '4. Exit'
)


class Document:
