secret_key = secrets.token_urlsafe(50)

settings.configure(
    DEBUG=False,
    SECRET_KEY=secret_key,
    ROOT_URLCONF=__name__,
    TEMPLATES=[
        {
            'BACKEND': 'django.template.backends.django.DjangoTemplates',
            'DIRS': [],
        }
    ],
)


class Product:
    """A product available in the store."""

    def __init__(self, id, name, price):
        self.id = id
        self.name = name
        self.price = price


PRODUCTS = [
    Product(1, 'Laptop', 999.99),
    Product(2, 'Phone', 699.99),
    Product(3, 'Tablet', 399.99),
]


def _find_product(product_id):
    """Return the product with the given id, or None if there is no match."""
    return next((product for product in PRODUCTS if product.id == product_id), None)


def _product_list_item(product, include_detail_link=False):
    """Render a product as an HTML <li>, optionally with a detail-page link."""
    item = f'<li>{escape(product.name)} - ${escape(str(product.price))}'
    if include_detail_link:
        item += f' <a href="/product/{product.id}">View</a>'
    return item + '</li>'


class HomeView(View):
    """Home page with a product search form."""

    def get(self, request):
        return HttpResponse(
            '\n            <h1>Welcome to Our Store</h1>\n'
            '            <form action="/search" method="GET">\n'
            '                <input type="text" name="query" placeholder="Search products...">\n'
            '                <button type="submit">Search</button>\n'
            '            </form>\n'
            '            <a href="/products">View All Products</a>\n        '
        )


class ProductListView(View):
    """List every product in the catalog."""

    def get(self, request):
        products_html = ''.join(
            _product_list_item(product, include_detail_link=True)
            for product in PRODUCTS
        )
        return HttpResponse(
            '\n            <h1>Our Products</h1>\n'
            f'            <ul>{products_html}</ul>\n'
            '            <a href="/">Back to Home</a>\n        '
        )


class ProductDetailView(View):
    """Show a single product, or a 404 response when it does not exist."""

    def get(self, request, product_id):
        product = _find_product(product_id)
        if not product:
            return HttpResponse('Product not found', status=404)
        return HttpResponse(
            f'\n            <h1>{escape(product.name)}</h1>\n'
            f'            <p>Price: ${escape(str(product.price))}</p>\n'
            '            <a href="/products">Back to Products</a>\n        '
        )


class SearchView(View):
    """Search products by name using the "query" GET parameter."""

    def get(self, request):
        query = escape(request.GET.get('query', ''))
        results = [product for product in PRODUCTS if query.lower() in product.name.lower()]
        if not results:
            return HttpResponse(
                '\n                <h1>Search Results</h1>\n'
                f'                <p>No products found for "<span style="color:red">{query}</span>"</p>\n'
                '                <a href="/products">View All Products</a>\n            '
            )
        results_html = ''.join(_product_list_item(product) for product in results)
        return HttpResponse(
            '\n            <h1>Search Results</h1>\n'
            f'            <p>Results for "<span style="color:red">{query}</span>":</p>\n'
            f'            <ul>{results_html}</ul>\n'
            '            <a href="/products">Back to Products</a>\n        '
        )


urlpatterns = [
    path('', HomeView.as_view()),
    path('products/', ProductListView.as_view()),
    path('product/<int:product_id>/', ProductDetailView.as_view()),
    path('search/', SearchView.as_view()),
]

app = get_wsgi_application()

if __name__ == '__main__':
