SALT_HEX_BYTES = 16
PBKDF2_HASH_NAME = 'sha256'
PBKDF2_ITERATIONS = 100000

# Authentication cookie settings.
AUTH_COOKIE_SECRET_BYTES = 64

TEMPLATES_DIR = 'templates'

HOME_TEMPLATE = '''<!DOCTYPE html>
<html>
<head><title>Home</title></head>
