        salt, hashed = stored.split(':')
        return hashed == self._pbkdf2_hex(password, salt)

    @staticmethod
    def _pbkdf2_hex(password, salt):
        """Return the hex PBKDF2-HMAC digest of ``password`` with ``salt``."""
        return hashlib.pbkdf2_hmac(
            PBKDF2_HASH_NAME,
            password.encode(),
            salt.encode(),
            PBKDF2_ITERATIONS,
        ).hex()


