    return [member.value for member in enum_class]


def _json_request_data() -> Any:
    """Return the parsed JSON body, or the ``_NOT_JSON`` sentinel.

    The sentinel lets callers distinguish "request is not JSON" from a
    JSON body that itself decodes to ``None`` (matching the behaviour of
    the original implementation).
    """
