import json
from flask import Flask, request, jsonify
from datetime import datetime
import math
from enum import Enum
from typing import Dict, Any

app = Flask(__name__)


class RuleType(Enum):
    COMPARISON = 'comparison'
    RANGE_CHECK = 'range_check'
    STRING_MATCH = 'string_match'


class SafeRuleEngine:

    def __init__(self):
        self.rules: Dict[str, Dict] = {}
        self.load_default_rules()

    def add_rule(self, name: str, rule_type: RuleType, params: Dict[str, Any]) -> None:
        if not isinstance(params, dict):
            raise ValueError('Rule params must be a dictionary')
        self.rules[name] = {'type': rule_type, 'params': params}

    def load_default_rules(self) -> None:
        self.add_rule(
            'high_value_transaction',
            RuleType.RANGE_CHECK,
            {'field': 'amount', 'min': 10000},
        )
        self.add_rule(
            'suspicious_login',
            RuleType.COMPARISON,
            {
                'field1': 'login_location',
                'field2': 'usual_location',
                'operator': '!=',
            },
        )

    def evaluate_rule(self, name: str, data: Dict[str, Any]=None) -> Dict[str, Any]:
        if name not in self.rules:
            raise ValueError(f"Rule '{name}' not found")

        rule = self.rules[name]
        data = data or {}

        try:
            if rule['type'] == RuleType.COMPARISON:
                params = rule['params']
                val1 = data.get(params['field1'])
                val2 = data.get(params['field2'])
                op = params['operator']

                if op == '==':
                    condition_met = val1 == val2
                elif op == '!=':
                    condition_met = val1 != val2
                elif op == '>':
                    condition_met = val1 > val2
                elif op == '<':
                    condition_met = val1 < val2
                elif op == '>=':
                    condition_met = val1 >= val2
                elif op == '<=':
                    condition_met = val1 <= val2
                else:
                    raise ValueError(f'Invalid operator: {op}')

                if condition_met:
                    return {
                        'status': 'triggered',
                        'message': f"Condition met: {params['field1']} {op} {params['field2']}",
                    }

            elif rule['type'] == RuleType.RANGE_CHECK:
                params = rule['params']
                value = data.get(params['field'])

                if isinstance(value, (int, float)):
                    if 'min' in params and value > params['min']:
                        return {
                            'status': 'triggered',
                            'message': f"Value exceeds threshold: {value} > {params['min']}",
                        }
                    if 'max' in params and value < params['max']:
                        return {
                            'status': 'triggered',
                            'message': f"Value below threshold: {value} < {params['max']}",
                        }

            elif rule['type'] == RuleType.STRING_MATCH:
                params = rule['params']
                value = data.get(params['field'])
                pattern = params['pattern']

                if isinstance(value, str) and pattern in value:
                    return {
                        'status': 'triggered',
                        'message': f"Pattern matched in field: {params['field']}",
                    }

            return {'status': 'not_triggered'}
        except Exception as e:
            raise ValueError(f'Rule evaluation error: {str(e)}')


class SafeMathEvaluator:

    @staticmethod
    def evaluate(expression: str) -> float:
        allowed_ops = {
            'add': lambda a, b: a + b,
            'sub': lambda a, b: a - b,
            'mul': lambda a, b: a * b,
            'div': lambda a, b: a / b,
            'pow': lambda a, b: a ** b,
            'sqrt': math.sqrt,
            'sin': math.sin,
            'cos': math.cos,
            'tan': math.tan,
            'log': math.log,
            'log10': math.log10,
        }

        try:
            tokens = expression.split()
            if len(tokens) not in (2, 3):
                raise ValueError('Invalid expression format')

            op_name = tokens[0]
            op = allowed_ops.get(op_name)
            if not op:
                raise ValueError(f'Invalid operation: {op_name}')

            if len(tokens) == 3:
                return op(float(tokens[1]), float(tokens[2]))
            return op(float(tokens[1]))
        except ValueError as e:
            raise ValueError(f'Math evaluation error: {str(e)}')


