import json
import os
from dataclasses import dataclass

from bottle import Bottle, request, response, template

app = Bottle()

DATA_FILE = 'user_data.json'

INDEX_TEMPLATE = """
        <form action="/search" method="post">
            <h2>User Search</h2>
            Name: <input name="name" type="text"><br>
