    data = load_data()
    data['users'].append(_build_user(request.forms))
    save_data(data)
    return ADD_USER_SUCCESS_MESSAGE


if __name__ == '__main__':
    init_data()
    app.run(host=SERVER_CONFIG.host, port=SERVER_CONFIG.port, debug=SERVER_CONFIG.debug)
