        result = eval(data['expression'], _build_eval_environment(data['value']))
        return jsonify({'valid': bool(result)})
    except Exception as e:
        return (jsonify({'error': str(e)}), HTTP_BAD_REQUEST)


# ---------------------------------------------------------------------------
# Entry point
# ---------------------------------------------------------------------------

if __name__ == '__main__':
